new:
    self.external_provider_status =
        ExternalAgentProviderStatus::visual_fixture(ExternalAgentProviderKind::ClaudeCode);

    let inventory = InstalledModelInventory {
        endpoint: DEFAULT_LOCAL_MODEL_ENDPOINT.to_owned(),
        backend_version: Some("0.12.4".to_owned()),
        models: vec![
            InstalledLocalModel {
                name: "gameengine-qwen-fixture:q4".to_owned(),
                digest: Some("sha256:0156qwenfixture".to_owned()),
                size_bytes: Some(8_400_000_000),
                parameter_size: Some("14B".to_owned()),
                quantization_level: Some("Q4_K_M".to_owned()),
                family: Some("qwen".to_owned()),
            },
            InstalledLocalModel {
                name: "gameengine-gemma-fixture:q4".to_owned(),
                digest: Some("sha256:0156gemmafixture".to_owned()),
                size_bytes: Some(7_900_000_000),
                parameter_size: Some("12B".to_owned()),
                quantization_level: Some("Q4_K_M".to_owned()),
                family: Some("gemma".to_owned()),
            },
        ],
    };
    let models = inventory
        .models
        .iter()
        .map(|model| model_identity("ollama-compatible", &model.name, Some(&inventory)))
        .collect::<Vec<_>>();
    self.installed_model_inventory = Some(inventory);
    self.benchmark_hardware = BenchmarkHardwareIdentity {
        platform: "windows-x86_64".to_owned(),
        gpu: TelemetryValue::Measured("Visual Validation GPU".to_owned()),
        total_gpu_memory_bytes: TelemetryValue::Measured(12 * 1024 * 1024 * 1024),
        total_system_memory_bytes: TelemetryValue::Measured(32 * 1024 * 1024 * 1024),
    };
    self.benchmark_campaign_models = models
        .iter()
        .map(|model| model.model_id.clone())
        .collect();
    self.benchmark_campaign_tasks = BENCHMARK_TASKS
        .iter()
        .map(|task| task.id.to_owned())
        .collect();
    self.benchmark_campaign_repetitions = DEFAULT_CAMPAIGN_REPETITIONS;
    self.benchmark_campaign_profile = CampaignExecutionProfile::Warm;
    let tasks = BENCHMARK_TASKS
        .iter()
        .enumerate()
        .map(|(index, task)| CampaignTaskPlan::for_task(task.id, 0x0156_0000_u64 + index as u64))
        .collect::<Result<Vec<_>, _>>();
    if let Ok(tasks) = tasks
        && let Ok(mut campaign) = BenchmarkCampaign::new(BenchmarkCampaignPlan {
            schema_version: CAMPAIGN_SCHEMA_VERSION,
            corpus_version: BENCHMARK_CORPUS_VERSION.to_owned(),
            benchmark_harness_version: BENCHMARK_HARNESS_VERSION.to_owned(),
            campaign_harness_version: CAMPAIGN_HARNESS_VERSION.to_owned(),
            schedule_version: CAMPAIGN_SCHEDULE_VERSION.to_owned(),
            candidates: models
                .iter()
                .cloned()
                .map(|model| CampaignCandidate {
                    model,
                    source: CampaignCandidateSource::installed(),
                })
                .collect(),
            tasks,
            repetitions: DEFAULT_CAMPAIGN_REPETITIONS,
            comparison_class: CampaignComparisonClass::ModelComparison,
            execution_profile: CampaignExecutionProfile::Warm,
            execution_environments: vec![CampaignExecutionEnvironment::CompatibleBackend],
            quality: QualityPreference::Balanced,
            hardware: self.benchmark_hardware.clone(),
            workload_policy_version: WORKLOAD_POLICY_VERSION.to_owned(),
            sampling_profile: "provider-default-uncontrolled".to_owned(),
            seed_policy: CampaignSeedPolicy::ProviderUnavailable,
        })
    {
        let preflight = campaign.preflight(&models).ok();
        if campaign.start(&models).is_ok() {
            if let Some(run) = campaign.runs.get_mut(0) {
                run.status = CampaignRunStatus::Completed;
            }
            if let Some(run) = campaign.runs.get_mut(1) {
                run.status = CampaignRunStatus::Completed;
            }
            if let Some(run) = campaign.runs.get_mut(2) {
                run.status = CampaignRunStatus::Failed;
            }
            let _ = campaign.pause();
            self.benchmark_campaign_preflight = preflight;
            self.benchmark_campaign = Some(campaign);
        }
    }
}
